                            asn1.Numbers.Integer,
                            asn1.Types.Primitive,
                            asn1.Classes.Universal,
                        )
                        self._encoder.write(
                            kbag.iv,
                            asn1.Numbers.OctetString,
                            asn1.Types.Primitive,
                            asn1.Classes.Universal,
                        )
